class NomPartidagasto extends BaseNomPartidagasto {

    /**
 * Obtener un listado de los datos de los tipos de pago.
 *
 * @param int       $inicio Inicio de la busqueda.
 * @param int       $limite Limite maximo de la busqueda.
 * @return array    Listado de los datos de los tipos de pago.
 */
    public static function obtenerListadoPartida($inicio = 0, $limite = 10) {

        //Devolviendo el listado de  partidas de pago en forma de arreglo.
        return Doctrine_Query::create()
            ->select('p.*,tp.denominacion as nomenclador')
            ->from('NomPartidagasto p')
            ->innerJoin('p.NomTipoPartidagasto tp')
            ->orderBy('denominacion')
            ->limit($limite)
            ->offset($inicio)
            ->fetchArray();
    }

    /**
     * Obtener un listado de los datos de los tipos de pago.
     *
     * @param int       $inicio Inicio de la busqueda.
     * @param int       $limite Limite maximo de la busqueda.
     * @return array    Listado de los datos de los tipos de pago.
     */
    public static function obtenerListadoNAE($inicio = 0, $limite = 10) {

        //Devolviendo el listado de  niveles de actividades economicas en forma de arreglo.
        return Doctrine_Query::create()
            ->select('*')
            ->from('NomPartidagasto')
            ->orderBy('denominacion')
            ->limit($limite)
            ->offset($inicio)
            ->fetchArray();
    }

    /**
     * Obtener un listado
     *
     * @return array    Listado de los datos
     */
    public static function obtenerTodosTipoPartidagasto() {

        //Devolviendo el listado  en forma de arreglo.
        return Doctrine_Query::create()
            ->from('NomPartidagasto')
            ->orderBy('denominacion')
            ->fetchArray();
    }

    public static function obtenerPartidasgasto() {

    //Devolviendo el listado  en forma de arreglo.
    return Doctrine_Query::create()->select('idpartidagasto as id, denominacion as text,true as leaf ')
        ->from('NomPartidagasto')
        ->orderBy('denominacion')
        ->fetchArray();
    }

    /**
     * Obtener la cantidad total
     *
     * @return int      Cantidad total .
     */
    public static function obtenerCantidadTotalPartida() {

        //Devolviendo la cantidad total de tipos de pago.
        return Doctrine_Query::create()->select('COUNT(idnivelactiveconom) AS cantidad')
            ->from('NomPartidagasto')
            ->fetchOne()
            ->cantidad;
    }

    /**
     * Obtener el tipo de pago dado el identificador.
     *
     * @param int $idtipopago    Identificador del tipo de pago.
     * @return NomTipoPago      Objeto tipo de pago (clase del dominio).
     */
    public static function obtenerObjPartidaPagoDadoId($idpartidagasto) {
        return Doctrine::getTable('NomPartidagasto')->find($idpartidagasto);
    }


    /**
     * Obtener si existe un tipo de partida a partir de la denominaci�n.
     *
     * @param int $idtipop    		Identificador .
     * @param string $denom    	 	Denominaci�n .
     *
     * @return boolean    			Si existe .
     */
    public static function existePartida($idpartidagasto, $denom) {

        $query = Doctrine_Query::create()->select('COUNT(idpartidagasto) AS cantidad')
            ->from('NomPartidagasto')
            ->where("denominacion ilike ?", $denom);
        if($idpartidagasto){
            $query->addWhere('idpartidagasto <> ?', $idpartidagasto);
        }

        return    $query->fetchOne()->cantidad;
    }













    /****************************VER DESDE AQUI*************************************************************/
    public static function existeDenominacionTipoPago($denominacion) {
        //Devolviendo la cantidad total de los salarios especificos.
        $query = new Doctrine_Query ();
        $result = $query->from('NomPartidagasto p')
            ->where("p.denominacion=?", array($denominacion))
            ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
            ->execute();
        if(count($result)){
            return 1;
        }else{
            return 0;
        }
    }

    public static function dameSeDesglosaDadoIdPago($idtipopartidagasto) {
        return Doctrine_Query::create()->select('p.sedesglosa AS sedesglosa')
            ->from('NomPartidagasto p')
            ->where('p.idtipopartidagasto = ?', array($idtipopartidagasto))
            ->fetchOne()
            ->sedesglosa;
    }

}
